for r,c,v in centers:
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  i,j=r+dr,c+dc
  # skip adjacent 3 arm
  if 0<=i<n and 0<=j<n and inp[i][j]==3: i+=dr;j+=dc
  while 0<=i<n and 0<=j<n:
   if inp[i][j]==3: break
   b[i][j]=v; i+=dr;j+=dc
for i in range(n):
 for j in range(n):
  if inp[i][j]==3:b[i][j]=3
  elif inp[i][j] in [1,2,4,8]: b[i][j]=inp[i][j]
